pragma solidity >=0.8.0;

contract Base {
    uint256 public baseState;

    function f(uint256 x) public virtual returns (uint256) {
        baseState = x + 1;
        return 100 + x;
    }

    // Internal call to a virtual function: must dispatch to the override in Child.
    function h(uint256 x) public returns (uint256) {
        return f(x);
    }
}

contract Child is Base {
    uint256 public childState;
    uint256 public lastResult;

    function f(uint256 x) public override returns (uint256) {
        childState = x + 2;
        return 200 + x;
    }

    // Overload distinguished by argument count from f(uint256).
    function f(uint256 x, uint256 y) public returns (uint256) {
        lastResult = 300 + x + y;
        return lastResult;
    }

    // External self-call dispatch to the overridden single-arg overload.
    function runDispatch(uint256 x) public returns (uint256) {
        lastResult = this.f(x);
        return lastResult;
    }
}
